tool_input.command:
cat >> statique/cadre.css <<'EOF'

/* Écran Lancement de la Chaîne (Story 7.15) */
.actions-chaine { display: flex; flex-wrap: wrap; gap: 24px; align-items: flex-start; }
.action-chaine { display: flex; flex-direction: column; gap: 6px; max-width: 420px; }
.action-chaine .legende { margin: 0; }
.bouton-primaire {
  min-height: var(--cible-min);
  padding: 0 20px;
  border: 1px solid var(--primaire);
  border-radius: 12px;
  background: var(--primaire);
  color: var(--blanc);
  font: 700 15px/1 var(--police-corps);
  cursor: pointer;
  align-self: flex-start;
}
.bouton-primaire:hover { background: var(--violet-2); }
.bouton-primaire[aria-disabled="true"],
.bouton-secondaire[aria-disabled="true"] {
  border-color: var(--bordure-champ);
  background: var(--fond);
  color: var(--encre-secondaire);
  cursor: not-allowed;
}
#resultat:not(:empty) { margin-top: 16px; }
#resultat .bandeau { font-weight: 400; }
.bandeau-texte { margin: 0; font-weight: 700; }
.bandeau-erreur {
  margin: 8px 0;
  padding: 8px 12px;
  border-radius: 8px;
  background: var(--blanc);
  font: 400 13px/1.5 var(--police-code);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.bandeau-complement { margin: 8px 0 0; }

.progression-ligne { display: flex; justify-content: space-between; margin: 0 0 6px; }
.progression { height: 12px; border-radius: 9999px; background: var(--lavande); overflow: hidden; }
.progression-barre { height: 100%; width: 0; background: var(--primaire); transition: width 0.3s; }
.etapes { list-style: decimal inside; margin: 16px 0 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.etape { padding: 8px 12px; border: 1px solid var(--bordure); border-radius: 12px; }
.etape p { margin: 0; display: inline-flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.etape .legende { display: block; margin-top: 2px; }
.etape--en_cours { border-color: var(--primaire); background: var(--lavande); }
.etape--reussie .etape-etat { background: var(--succes-fond); color: var(--succes-texte); }
.etape--echouee { border-color: var(--erreur-texte); }
.etape--echouee .etape-etat { background: var(--erreur-fond); color: var(--erreur-texte); }
.journal { list-style: none; margin: 8px 0 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
EOF
sed -i 's/<p class="sr-seul" id="annonce" role="status"><\/p>/&/' statique/chaine.html; grep -n "etape-tete" statique/chaine.js
